package app.kinkeep.data

import androidx.room.migration.Migration

/**
 * Release 1.0 ships database version 1. From now on, every change to the stored data needs:
 *   1. a higher `version` in [KinDatabase],
 *   2. a Migration from the previous version, added to this list,
 *   3. the new schema file from app/schemas committed (it is generated by the build).
 * Without a migration the app would refuse to open people's existing data after an update.
 */
val ALL_MIGRATIONS: Array<Migration> = arrayOf()
